package com.tuap.backend.auth;
import static org.junit.jupiter.api.Assertions.*; import org.junit.jupiter.api.Test;
class PendingSocialAuthExceptionHandlerTest { @Test void mapsNeutralErrorAndKeepsGoogleSeparate(){AuthExceptionHandler h=new AuthExceptionHandler();ApiErrorResponse p=h.invalidPendingSocialAuth(new InvalidPendingSocialAuthException()).getBody();assertEquals("INVALID_PENDING_SOCIAL_AUTH",p.code());assertEquals(400,p.status());assertEquals("INVALID_GOOGLE_TOKEN",h.invalidGoogleToken(new InvalidGoogleTokenException()).getBody().code());assertEquals("INVALID_APPLE_TOKEN",h.invalidAppleToken(new InvalidAppleTokenException()).getBody().code());assertEquals("APPLE_AUTH_DISABLED",h.appleDisabled(new AppleAuthDisabledException()).getBody().code());assertEquals("APPLE_ACCOUNT_INACTIVE",h.inactiveAppleAccount(new AppleAccountInactiveException()).getBody().code());}}
